import React from "react";
import Select from "react-select";


function ColumnSelect({ column, selectValue, setSelectValue }) {
    const uniqueValues = React.useMemo(() => {
        const values = column.getFacetedRowModel().flatRows.map(row => row.getValue(column.id)).flat()
        const uniqueValues = Array.from(new Set(values)).sort()
        return uniqueValues.map(e => {
            return {value: e, label: e}
        })
    })

    function handleSelectChange(values) {
        setSelectValue(values)
        column.setFilterValue(values.map(e => e.value))
    }

    return (
        <Select 
            value={selectValue}
            options={uniqueValues}
            isMulti
            onChange={handleSelectChange}
            classNamePrefix="react-select"
        />
    )
}

export default ColumnSelect