import { createColumnHelper } from "@tanstack/react-table";
import { Dex } from "@pkmn/dex";
import { Generations } from '@pkmn/data';
import "../assets/spritesheet-2DWIAUAU.css"
import "../assets/types.css"


const columnHelper = createColumnHelper();

const gens = new Generations(Dex);
const Gen = gens.get(9)

function renderName(cell){
    const smogonUrl = "https://www.smogon.com/dex/sv/pokemon/";
    const smogonSlug = cell.getValue().toLowerCase().replaceAll(" ", "-").replaceAll("'", "").replaceAll("é", "e").replaceAll("%", "").replaceAll("’", "").replaceAll(".", "");
    return (
        <span className="pokemon-name">
            <span className="PokemonSprite is-normalized-width">
                <span className={"sprite-" + smogonSlug} />
            </span>
            <a href={smogonUrl + smogonSlug}>{cell.getValue()}</a>
        </span>
    );
}

function renderTypes(cell){
    const smogonUrl = "https://www.smogon.com/dex/sv/types/";
    return (
        <ul className="TypeList">
            {cell.getValue().map((type, idx) => {
                return (
                    <li key={idx}>
                        <a className={"Type " + type.toLowerCase()} href={smogonUrl + type}>{type}</a>
                    </li>
                );
            })}
        </ul>
    );
}

function renderAbilities(cell){
    const smogonUrl = "https://www.smogon.com/dex/sv/abilities/";
    return (
        <ul>
            {cell.getValue().map((ability, index) => {
                return (
                    <li key={index}>
                        <a href={smogonUrl + ability}>{ability.replaceAll("-", " ")}</a>
                    </li>
                );
            })}
        </ul>
    );
}

function renderStat(cell){
    return (
        <div className="stat-cell">
            <div className="stat">{cell.column.columnDef.header}</div>
            <span>{cell.getValue()}</span>
        </div>
    );
}

export const columnDef = [
    columnHelper.accessor("name", {
        header: "Name",
        cell: renderName
    }),
    columnHelper.accessor("types", {
        header: "Type",
        cell: renderTypes,
        filterFn: "arrIncludesAll"
    }),
    columnHelper.accessor("abilities", {
        header: "Abilities",
        cell: renderAbilities,
        filterFn: "arrIncludesSome"
    }),
    columnHelper.accessor("cost", {
        header: "Cost",
    }),
    columnHelper.accessor("baseStats.hp", {
        header: "HP",
        cell: renderStat
    }),
    columnHelper.accessor("baseStats.atk", {
        header: "Atk",
        cell: renderStat
    }),
    columnHelper.accessor("baseStats.def", {
        header: "Def",
        cell: renderStat
    }),
    columnHelper.accessor("baseStats.spa", {
        header: "SpA",
        cell: renderStat
    }),
    columnHelper.accessor("baseStats.spd", {
        header: "SpD",
        cell: renderStat
    }),
    columnHelper.accessor("baseStats.spe", {
        header: "SpE",
        cell: renderStat
    }),
    columnHelper.accessor("bst", {
        header: "BST",
        cell: renderStat
    }),
    columnHelper.accessor("phys_bulk", {
        header: "PBlk",
        cell: renderStat
    }),
    columnHelper.accessor("spc_bulk", {
        header: "SBlk",
        cell: renderStat
    }),
    columnHelper.accessor("learnset", {
        filterFn: "arrIncludesSome"
    }),
];